import { useEffect, useState } from "react";
import { io } from "socket.io-client";
import "./PatientDashboard.css";

const socket = io("http://localhost:5000");

function PatientDashboard() {

  const [myOP,setMyOP]=useState(null);

  const [form,setForm]=useState({

    patientName:"",

    department:"",

    date:""

  });

  const [queueCount,setQueueCount]=useState(0);

  const [notification,setNotification]=useState("");



  useEffect(()=>{

    const fetchData = async()=>{

      try{

        const res =
        await fetch(
          "http://localhost:5000/api/queue/all"
        );

        const data =
        await res.json();



        const mine =
        data.find(

          q=>

          q.patientName===

          form.patientName

        );



        if(mine){

          setMyOP(
            mine
          );

        }

        else{

          setMyOP(
            null
          );

          setNotification(
            ""
          );

          setForm(prev=>({
            
            ...prev,

            department:"",

            date:""

          }));

        }



        const waitingPatients =
        data.filter(

          q=>

          q.status===

          "InQueue"

        );



        setQueueCount(

          waitingPatients.length

        );



        if(mine){

          const position =

          waitingPatients.findIndex(

            q=>

            q._id===

            mine._id

          );



          if(

            position>=0 &&

            position<3

          ){

            setNotification(

              "🔔 Your queue is near"

            );

          }

          else{

            setNotification(
              ""
            );

          }

        }

      }

      catch(err){

        console.log(
          err
        );

      }

    };



    fetchData();



    socket.on(

      "queueUpdated",

      fetchData

    );



    return()=>{

      socket.off(

        "queueUpdated"

      );

    };

  },[form.patientName]);



  const bookOP = async()=>{

    try{

      const res =
      await fetch(

        "http://localhost:5000/api/queue/book",

        {

          method:"POST",

          headers:{

            "Content-Type":

            "application/json"

          },

          body:

          JSON.stringify(
            form
          )

        }

      );



      const data =

      await res.json();



      setMyOP(
        data
      );

    }

    catch(err){

      console.log(
        err
      );

    }

  };



  const joinQueue = async(id)=>{

    try{

      await fetch(

        `http://localhost:5000/api/queue/join/${id}`,

        {

          method:"PUT"

        }

      );

    }

    catch(err){

      console.log(
        err
      );

    }

  };



  return(

<div className="patient-container">

<div className="patient-card">

<h1>

🏥 HealSync

</h1>



{

notification && (

<div className="queue-box">

{notification}

</div>

)

}



{

!myOP && (

<>

<input

placeholder=
"Patient Name"

value={
form.patientName
}

onChange={(e)=>

setForm({

...form,

patientName:
e.target.value

})

}

/>



<input

placeholder=
"Department"

value={
form.department
}

onChange={(e)=>

setForm({

...form,

department:
e.target.value

})

}

/>



<input

type="date"

value={
form.date
}

onChange={(e)=>

setForm({

...form,

date:
e.target.value

})

}

/>



<button

onClick={
bookOP
}

>

Book OP

</button>

</>

)

}



{

myOP && (

<div className="op-card">

<h2>

My OP

</h2>



<p>

Token :

{myOP.tokenNumber}

</p>



<p>

Department :

{myOP.department}

</p>



<p>

Status :

{myOP.status}

</p>



{

myOP.status===

"Confirmed" && (

<button

className=
"join-btn"

onClick={()=>

joinQueue(

myOP._id

)

}

>

Join Queue

</button>

)

}



{

myOP.status===

"InQueue" && (

<div className="queue-box">

Queue Waiting

<h3>

{queueCount}

</h3>

</div>

)

}

</div>

)

}

</div>

</div>

);

}

export default PatientDashboard;
